import { useState } from "react";
import { Avatar, AvatarFallback } from "./ui/avatar";
import { Button } from "./ui/button";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "./ui/dropdown-menu";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "./ui/dialog";
import { Input } from "./ui/input";
import { Label } from "./ui/label";
import { User, LogIn, LogOut, Settings, UserPlus } from "lucide-react";

export function AccountMenu({
    isLoggedIn,
    userName = "User",
    onLogin,
    onLogout,
    onRegister
}) {
    const [loginOpen, setLoginOpen] = useState(false);
    const [registerOpen, setRegisterOpen] = useState(false);
    const [loginForm, setLoginForm] = useState({ email: "", password: "" });
    const [registerForm, setRegisterForm] = useState({ name: "", email: "", password: "" });

    const handleLogin = (e) => {
        e.preventDefault();
        onLogin(loginForm.email, loginForm.password);
        setLoginForm({ email: "", password: "" });
        setLoginOpen(false);
    };

    const handleRegister = (e) => {
        e.preventDefault();
        onRegister(registerForm.email, registerForm.password, registerForm.name);
        setRegisterForm({ name: "", email: "", password: "" });
        setRegisterOpen(false);
    };

    if (!isLoggedIn) {
        return (
            <div className="flex gap-2">
                <Dialog open={loginOpen} onOpenChange={setLoginOpen}>
                    <DialogTrigger asChild>
                        <Button variant="outline" size="sm" className="bg-gradient-to-r from-blue-600 to-slate-700 text-white border-none hover:from-blue-700 hover:to-slate-800">
                            <LogIn className="w-4 h-4 mr-2" />
                            Login
                        </Button>
                    </DialogTrigger>
                    <DialogContent>
                        <DialogHeader>
                            <DialogTitle>Login to your account</DialogTitle>
                        </DialogHeader>
                        <form onSubmit={handleLogin} className="space-y-4">
                            <div>
                                <Label htmlFor="email">Email</Label>
                                <Input
                                    id="email"
                                    type="email"
                                    value={loginForm.email}
                                    onChange={(e) => setLoginForm(prev => ({ ...prev, email: e.target.value }))}
                                    required
                                />
                            </div>
                            <div>
                                <Label htmlFor="password">Password</Label>
                                <Input
                                    id="password"
                                    type="password"
                                    value={loginForm.password}
                                    onChange={(e) => setLoginForm(prev => ({ ...prev, password: e.target.value }))}
                                    required
                                />
                            </div>
                            <Button type="submit" className="w-full bg-gradient-to-r from-blue-600 to-slate-700 hover:from-blue-700 hover:to-slate-800">
                                Login
                            </Button>
                        </form>
                    </DialogContent>
                </Dialog>

                <Dialog open={registerOpen} onOpenChange={setRegisterOpen}>
                    <DialogTrigger asChild>
                        <Button variant="outline" size="sm" className="bg-gradient-to-r from-gray-600 to-slate-700 text-white border-none hover:from-gray-700 hover:to-slate-800">
                            <UserPlus className="w-4 h-4 mr-2" />
                            Register
                        </Button>
                    </DialogTrigger>
                    <DialogContent>
                        <DialogHeader>
                            <DialogTitle>Create an account</DialogTitle>
                        </DialogHeader>
                        <form onSubmit={handleRegister} className="space-y-4">
                            <div>
                                <Label htmlFor="name">Name</Label>
                                <Input
                                    id="name"
                                    type="text"
                                    value={registerForm.name}
                                    onChange={(e) => setRegisterForm(prev => ({ ...prev, name: e.target.value }))}
                                    required
                                />
                            </div>
                            <div>
                                <Label htmlFor="reg-email">Email</Label>
                                <Input
                                    id="reg-email"
                                    type="email"
                                    value={registerForm.email}
                                    onChange={(e) => setRegisterForm(prev => ({ ...prev, email: e.target.value }))}
                                    required
                                />
                            </div>
                            <div>
                                <Label htmlFor="reg-password">Password</Label>
                                <Input
                                    id="reg-password"
                                    type="password"
                                    value={registerForm.password}
                                    onChange={(e) => setRegisterForm(prev => ({ ...prev, password: e.target.value }))}
                                    required
                                />
                            </div>
                            <Button type="submit" className="w-full bg-gradient-to-r from-gray-600 to-slate-700 hover:from-gray-700 hover:to-slate-800">
                                Register
                            </Button>
                        </form>
                    </DialogContent>
                </Dialog>
            </div>
        );
    }

    return (
        <DropdownMenu>
            <DropdownMenuTrigger asChild>
                <Button variant="ghost" className="relative h-10 w-10 rounded-full p-0">
                    <Avatar className="h-10 w-10">
                        <AvatarFallback className="bg-gradient-to-r from-blue-500 to-slate-600 text-white">
                            {userName.charAt(0).toUpperCase()}
                        </AvatarFallback>
                    </Avatar>
                </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-56">
                <div className="flex items-center justify-start gap-2 p-2">
                    <div className="flex flex-col space-y-1 leading-none">
                        <p className="font-medium">{userName}</p>
                        <p className="w-[200px] truncate text-sm text-muted-foreground">
                            user@example.com
                        </p>
                    </div>
                </div>
                <DropdownMenuSeparator />
                <DropdownMenuItem>
                    <User className="mr-2 h-4 w-4" />
                    Profile
                </DropdownMenuItem>
                <DropdownMenuItem>
                    <Settings className="mr-2 h-4 w-4" />
                    Settings
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={onLogout}>
                    <LogOut className="mr-2 h-4 w-4" />
                    Log out
                </DropdownMenuItem>
            </DropdownMenuContent>
        </DropdownMenu>
    );
}
